// expect: exit 0
// screen: 0 sum 15, max 5
// screen: 1 Leap-C: 6 characters
int a[5] = { 1, 2, 3, 4, 5 };
char name[16];
int sum(int *p, int n)
{
    int s = 0;
    while (n--)
        s += *p++;
    return s;
}
int main(void)
{
    int i, max = a[0];
    for (i = 1; i < 5; i++)
        if (a[i] > max)
            max = a[i];
    cls();
    printf("sum %d, max %d\n", sum(a, 5), max);
    strcpy(name, "Leap");
    strcat(name, "-C");
    printf("%s: %d characters\n", name, strlen(name));
    return strcmp(name, "Leap-C");
}
